package lt.example.student;

import jakarta.xml.ws.BindingProvider;
import lt.example.student.client.generated.StudentService_Service;

/** Calls the SOAP service through classes generated by the wsimport tool. */
public class StudentClient {
    /** Creates a SOAP client. */
    public StudentClient() {
    }

    /**
     * Fetches a student from a running SOAP endpoint.
     *
     * @param id student identifier
     * @param endpointUrl SOAP endpoint address
     * @return student returned by the service, or {@code null}
     */
    public lt.example.student.client.generated.Student fetchStudent(
            int id, String endpointUrl) {
        var wsdl = StudentClient.class.getResource("/wsdl/student-service.wsdl");
        var service = new StudentService_Service(wsdl);
        var port = service.getStudentServicePort();
        ((BindingProvider) port).getRequestContext()
                .put(BindingProvider.ENDPOINT_ADDRESS_PROPERTY, endpointUrl);
        return port.getStudent(id);
    }
}
